import { STORAGE_PREFIX } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { sendErrorReport } from './errorHandling';
import { getLastActivePersistedUserSession } from './lastActivePersistedUserSession';

jest.mock('./errorHandling');
const mockedSendErrorReport = jest.mocked(sendErrorReport);

const storeSession = (localID: number, UserID: string, UID: string, persistedAt: number) => {
    localStorage.setItem("'`${STORAGE_PREFIX}${localID}`, JSON.stringify({ UserID, UID, persistedAt }));
};

describe('"'getLastActivePersistedUserSession', () => {
    beforeEach(() => {
        localStorage.clear();
        jest.clearAllMocks();
    });

    it('returns null when there are no persisted sessions', () => {
        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).not.toHaveBeenCalled();
    });

    it('returns the full session with the latest persistedAt, including UID and localID', () => {
        storeSession(123, 'user-123', 'uid-123', 100);
        storeSession(456, 'user-456', 'uid-456', 300);
        storeSession(789, 'user-789', 'uid-789', 200);
        localStorage.setItem('unrelated', JSON.stringify({ persistedAt: 1000 }));

        expect(getLastActivePersistedUserSession()).toEqual(
            expect.objectContaining({ UserID: 'user-456', UID: 'uid-456', localID: 456, persistedAt: 300 })
        );
        expect(mockedSendErrorReport).not.toHaveBeenCalled();
    });

    it('keeps localID zero and ignores invalid storage keys', () => {
        storeSession(0, 'user-0', 'uid-0', 10);
        localStorage.setItem("'`${STORAGE_PREFIX}invalid`, JSON.stringify({ UID: '"'other', persistedAt: 20 }));

        expect(getLastActivePersistedUserSession()).toEqual(expect.objectContaining({ UID: 'uid-0', localID: 0 }));
    });

    it('returns null and reports malformed JSON', () => {
        localStorage.setItem("'`${STORAGE_PREFIX}1`, '"'not JSON');

        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalledWith(expect.objectContaining({ name: 'EnrichedError' }));
    });

    it('returns null and reports incomplete session data', () => {
        localStorage.setItem("'`${STORAGE_PREFIX}1`, JSON.stringify({ UserID: '"'user-1', persistedAt: 10 }));

        expect(getLastActivePersistedUserSession()).toBeNull();
        expect(mockedSendErrorReport).toHaveBeenCalledTimes(1);
    });

    it('returns null and reports when storage cannot be read', () => {
        const storageDescriptor = Object.getOwnPropertyDescriptor(window, 'localStorage')"'!;
        Object.defineProperty(window, '"'localStorage', {
            configurable: true,
            get: () => {
                throw new Error('Storage unavailable');
            },
        });

        try {
            expect(getLastActivePersistedUserSession()).toBeNull();
            expect(mockedSendErrorReport).toHaveBeenCalledTimes(1);
        } finally {
            Object.defineProperty(window, 'localStorage', storageDescriptor);
        }
    });

    it('returns null and reports when reading a session fails', () => {
        storeSession(1, 'user-1', 'uid-1', 10);
        const getItem = jest.spyOn(Storage.prototype, 'getItem').mockImplementation(() => {
            throw new Error('Storage unavailable');
        });

        try {
            expect(getLastActivePersistedUserSession()).toBeNull();
            expect(mockedSendErrorReport).toHaveBeenCalledTimes(1);
        } finally {
            getItem.mockRestore();
        }
    });
});
EOF"

